package dev.metallicarts.domain;
import com.mojang.serialization.JsonOps;
import dev.metallicarts.arts.*;
import dev.metallicarts.equipment.*;
import dev.metallicarts.feruchemy.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class AdvancedFeruchemyTest {
 private static MemoryEntry memory(){return new MemoryEntry(UUID.randomUUID(),"route","Actual record","minecraft:overworld",1,80,2,100);}
 @Test void bodyEscrowRoundTripsAndRejectsImpossibleBalances(){var b=new BodyState(750,36000000,500,250,100,1500);assertEquals(b,BodyState.CODEC.parse(JsonOps.INSTANCE,BodyState.CODEC.encodeStart(JsonOps.INSTANCE,b).getOrThrow()).getOrThrow());assertThrows(IllegalArgumentException.class,()->b.air(-1));assertThrows(IllegalArgumentException.class,()->b.nutrition(BodyState.MAX_NUTRITION+1));assertThrows(IllegalArgumentException.class,()->b.temperature(45000001));}
 @Test void memoryCannotExistInTwoCanonicalPoolsAndIndexSurvivesReload(){var ledger=new MetalmindLedger();var lease=new AssetLease(UUID.randomUUID(),0);var identity=UUID.randomUUID();var a=ledger.claim(ledger.create(FeruchemicalAttribute.MEMORY,9000000,1,false).token(),lease);var m=memory();ledger.storeMemory(a.token(),lease,identity,m,false);var leaseB=new AssetLease(UUID.randomUUID(),1);var b=ledger.claim(ledger.create(FeruchemicalAttribute.MEMORY,9000000,1,false).token(),leaseB);assertThrows(IllegalArgumentException.class,()->ledger.storeMemory(b.token(),leaseB,identity,m,false));var saved=MetalmindLedger.CODEC.encodeStart(JsonOps.INSTANCE,ledger).getOrThrow();var loaded=MetalmindLedger.CODEC.parse(JsonOps.INSTANCE,saved).getOrThrow();assertThrows(IllegalArgumentException.class,()->loaded.storeMemory(b.token(),leaseB,identity,m,false));assertEquals(m,loaded.takeMemory(a.token(),lease,identity,m.id()).memory());assertEquals(1000,loaded.storeMemory(b.token(),leaseB,identity,m,false).charge());}
 @Test void genericMemoryChargeCannotMintOrEraseRecordedEntries(){var ledger=new MetalmindLedger();var lease=new AssetLease(UUID.randomUUID(),0);var a=ledger.claim(ledger.create(FeruchemicalAttribute.MEMORY,9000,1,false).token(),lease);assertThrows(IllegalArgumentException.class,()->ledger.change(a.token(),lease,UUID.randomUUID(),1000));assertEquals(0,ledger.resolve(a.token()).charge());}
 @Test void typedUnsealedContentRoundTripsWithoutLosingItsSpecificPower(){var ledger=new MetalmindLedger();var content=new MetalmindContent(Optional.of(new StoredPower(Art.FERUCHEMY,Metal.GOLD,1)),List.of(),false);var lease=new AssetLease(UUID.randomUUID(),0);var a=ledger.claim(ledger.create(FeruchemicalAttribute.INVESTITURE,9000,1,false,content).token(),lease);a=ledger.change(a.token(),lease,UUID.randomUUID(),2000,true);a=ledger.release(a.token(),lease);a=ledger.unseal(a.token());var loaded=MetalmindLedger.CODEC.parse(JsonOps.INSTANCE,MetalmindLedger.CODEC.encodeStart(JsonOps.INSTANCE,ledger).getOrThrow()).getOrThrow();assertEquals(a,loaded.resolve(a.token()));assertTrue(a.content().unsealed());assertEquals(Metal.GOLD,a.content().power().orElseThrow().metal());}
 @Test void legacyPhysicalAssetsLoadWithoutNewOptionalContent(){var ledger=new MetalmindLedger();ledger.create(FeruchemicalAttribute.WEIGHT,9000,1,false);var json=MetalmindLedger.CODEC.encodeStart(JsonOps.INSTANCE,ledger).getOrThrow();for(var a:json.getAsJsonObject().getAsJsonArray("assets"))a.getAsJsonObject().remove("content");assertEquals(MetalmindContent.EMPTY,MetalmindLedger.CODEC.parse(JsonOps.INSTANCE,json).getOrThrow().all().getFirst().content());}
 @Test void foreignKeysCannotBeErasedByFullIdentitySuppression(){var ledger=new MetalmindLedger();var lease=new AssetLease(UUID.randomUUID(),0);var a=ledger.claim(ledger.create(FeruchemicalAttribute.WEIGHT,9000,1,false).token(),lease);var owner=UUID.randomUUID();ledger.change(a.token(),lease,owner,1000,false);assertThrows(IllegalArgumentException.class,()->ledger.change(a.token(),lease,UUID.randomUUID(),1000,true));assertEquals(Optional.of(owner),ledger.resolve(a.token()).identity());}
 @Test void everyMetalHasAnAttributeAndTinHasExactlyFiveIndependentTypes(){for(var m:Metal.values())assertTrue(Arrays.stream(FeruchemicalAttribute.values()).anyMatch(a->a.metal()==m));assertEquals(5,Arrays.stream(FeruchemicalAttribute.values()).filter(a->a.metal()==Metal.TIN).count());}
}
